ments')->where('department_id',$data->department_id)->get();	if($dep->num_rows()>0)	{		foreach($dep->result() as $depp)	$depart=$depp->department;			}else{		$depart='';	}	/** END **/	/** Get Approved By Name **/	$dep=$this->db->select('first_name,last_name')->from('system_users')->where('user_id',$data->approvedBy)->get();	if($dep->num_rows()>0)	{		foreach($dep->result() as $depp)	$appby=$depp->first_name." ".$depp->last_name;			}else{		$appby='';	}	/** END **/			/** GET VENDOR **/	$ven=$this->db->select('*')->from('vendors')->where('id',$data->vendor)->get();	if($ven->num_rows()>0)	{		foreach($ven->result() as $ven1);		$vname=$ven1->name;		if($ven1->phone<>0)		{		$vphone=$ven1->phone;		}else{						$vphone='';		}		$vemail=$ven1->email;		$vgst=$data->gst;		$vendorgst=$ven1->gst;		//	$gstpercentage = $ven1->gst_percentage;		$vaddress=$ven1->address;		$payterm=$ven1->payment_terms;		$frieght=$ven1->deliveryby;			}else{				$vname='';		$vphone='';		$vemail='';		$vgst='';		$vaddress='';		$payterm='';		$vendorgst='';	//	$gstpercentage="";        $frieght='';			}	/** END **/														?>								<div class="container printhide" style="margin-top:20px;margin-bottom:20px">    <div class="row text-center">    <span class="btn btn-success" style="text-align:center" onclick="printDiv(<?php echo $data->approved;?>);">PRINT PO</span>                </div>    </div>    <page size="A4">    	<div class="pageinside-invoice">			<div class="row">			  				<div class="col-sm-12">					<h3 style="text-align:center;font-weight: 700;margin:8px 0;margin-bottom: 0px;"><!--<img src="<?php echo assets_url;?>logo.png" alt="" height="50">-->PRESTO STANTEST PVT. LTD.</h3>					<p class="address uppercase">I-42, DLF INDUSTRIAL Area, PHASE-1<br/>FARIDABAD HARYANA-121003<br/>PHONES: 0129-4272727 / 0129-4083111<br/>Email: purchase@prestogroup.com<br/><strong>GSTN:  06AAACP9778K1ZR</strong></p>				</div>			</div>						<div class="row">				<div class="col-sm-12">					<table class="table tablenoborder" style="border-bottom:2px solid #333;margin-bottom:0">						<thead>							<tr class="border">								<th colspan="2" style="font-size: 17px;">PURCHASE ORDER <div id="potypees"></div></th>							</tr>						</thead>												 														<tbody>							<tr>								<td class="w50" style="border-right:1px solid #333">									<table class="tablepodetail w80" style="text-align:left">										<tr>											<th>TO.</th>											<td style="text-align:left">: <?php echo $vname;?></td>										</tr>																			      <tr>											<th style="text-align:left">ADDRESS</th>											<td style="text-align:left">:<?php echo $vaddress;?></td>																						</tr>																																	<?php											$jobcard='';																													if($data->source==1)											{																								$job=$this->db->select('job_card_no')->from('order_instruments')->where('id',$data->jobcard)->get();												if($job->num_rows()>0)												{													foreach($job->result() as $job1);																										$jobcard='Jobcard-'.$job1->job_card_no;																									}else{																										$jobcard='';												}											}else if($data->source==2)											{												/** Intend **/																								$indno=$CI->Store_model->getindentno($data->prno);																										$jobcard='INDENT- IND'.$indno;																																				}																							?>																						<tr>											<th style="text-align:left">PHONE</th>											<td style="text-align:left">: <?php echo $vphone;?></td>																						</tr>																							<tr>											<th style="text-align:left">EMAIL</th>											<td style="text-align:left">: <?php echo $vemail;?></td>																						</tr>																						<tr>											<th>GSTN</th>											<td style="text-align:left">: <?php echo $vendorgst;?></td>										</tr>																																																</table>								</td>								<td class="w50">						