y),2);?></td>													   													      <td class="hideprice"><?php echo floatval($gstpercentage);?> %</td>                                                                                                            <?php									if($vendorgst<>''){																	$statecode = substr($vendorgst,0,2);									if($statecode=='06'){									$tamount = round(floatval($totwithqty),2);									$cgstsgst = $gstpercentage/2;									$gstamount = $tamount*$cgstsgst/100;									$gstftotal[] = $gstamount;									$finalgstamount = $tamount*$gstpercentage/100;									$totalinarray[] = $tamount*$gstpercentage/100;									$colps=2;								?>								<td style="text-align:center"><?php echo $gstamount;?></td>								<td style="text-align:center"><?php echo $gstamount;?></td>									<?php }else{										$tamount = round(floatval($totwithqty),2);										$finalgstamount = $tamount*$gstpercentage/100;										$totalinarray[] = $tamount*$gstpercentage/100;										$gstftotal[] = $finalgstamount;										$colps=1;										?>									<td style="text-align:center"><?php echo $finalgstamount;?></td>									<?php }?>		<?php } ?>	    																																												                                                                                                              											                                                                                                          </tr>																									<?php											$i++;											}																							$colspannnnn=9+$colps;										$colspannnnn1=5+$colps;												?>																				  							<tr class="totalamtrow">								<td colspan="<?php echo $colspannnnn1;?>">									Payment Term: <?php echo $payterm;?> Days<br/>									Freight Terms: <?php echo $frieght;?>																	</td>																<td><p style="text-align:right;font-weight:500;margin:0">Total :</p></td>								<?php								if(count($cost)>0)								{									$totpr=array_sum($cost);								}else{									$totpr=0;								}								?>								<td style="text-align:center"><?php echo $totpr;?></td>								 <?php								 //echo "<pre>"; print_r($gstftotal); exit;								if($vendorgst<>''){																	$statecode = substr($vendorgst,0,2);									if($statecode=='06'){																	?>								<td style="text-align:center"><?php echo array_sum($gstftotal);?></td>								<td style="text-align:center"><?php echo array_sum($gstftotal);?></td>									<?php }else{																				?>									<td style="text-align:center"><?php echo array_sum($gstftotal);?></td>									<?php }?>		<?php } ?>	    	    																												</tr>							<?php						$colspannnnn=10+$colps;						?>						<tr>								<td colspan="<?php echo $colspannnnn;?>" style="border:1px solid #333;padding:4px 6px;font-size:10px;font-style:italics;">Remarks: <?php echo $rmk;?></i></td>							</tr>						<tr>								<td colspan="<?php echo $colspannnnn;?>" style="border:1px solid #333;padding:4px 6px;font-size:10px;font-style:italics;">Instructions : <i><?php echo $instruction;?></i></td>							</tr>													</tbody>					</table>								</div>		<div class="col-sm-6">				    <p style="font-weight:bold;">&nbsp;&nbsp;Raised by: <?php echo ucfirst($data->first_name);?> <?php echo ucfirst($data->last_name);?></p>				      <p style="font-weight:bold;">&nbsp;&nbsp;Approved by: <?php echo ucwords($appby);?></p>				    <p style="font-weight:bold;">&nbsp;&nbsp;FOR PRESTO STANTEST PVT LTD</p>					<p style="font-weight:bold;">&nbsp;&nbsp;</p>													    <p style="font-weight:bold;">&nbsp;&nbsp;Authorized Signatory:</p>				    				    				</div>								<div class="col-sm-5">				    <table class="table hideprice" border="1" style="text-align:center;margin-bottom:2px;margin-left:65px;">				        <thead>				            <tr>				                <th style="text-align:center">Grand Total</th>								<?php								if(count($cost)>0)								{																		$tot=array_sum($cost)+array_sum($totalinarray);									}else{	$tot=0;}$amountinwords = ucwords($CI->Store_model->getIndianCurrency(round($tot)));								?>				                <th style="text-align:right;width:60px;"><?php echo number_format($tot,2);?></th>				            </tr>				            				             <tr>				                <th colspan="2" style="text-align:center"><?php echo $amountinwords;?></th>				            				            </tr>				              				            				        </thead>				        				        				    </table>				</div>			<div class="col-sm-1"></div>			<br/><br/><br/><br/>						        </div>    </page>		<?php	}	?>	<script src="https://ajax.googleapis.com/ajax/libs/jquery/1.11.3/jquery.min.js"></script><script>function printDiv(status) {if(status!=1)	{		alert('Po cannot be printed since it is unapproved');		return false;	}else{  window.print();  	}}		$( document ).ready(function() {			var pono="<?php echo $this->uri->segment(3);?>";html2canvas(document.getElementById('poinvoice')).then(function(canvas) {    background :'#FFFFFF',var base64URL = canvas.toDataURL('image/png').replace('image/png', 'image/octet-stream');// AJAX request$.ajax({url: '<?php echo page_url;?>Store/savepoimage',type: 'post',data: {image: base64URL,ponumber:pono},success: function(data){}});});			//	window.print();	});</script>	</body></html>